#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

int main(void) {
    const char message[] = "hola desde write\n";
    ssize_t written = write(STDOUT_FILENO, message, sizeof message - 1);

    if (written == -1) {
        fprintf(stderr, "write: %s\n", strerror(errno));
        return 1;
    }

    printf("bytes escritos: %zd\n", written);
    return 0;
}
